from pathlib import Pathimport numpy as npimport pandas as pdROOT = Path(__file__).resolve().parent.parentDATA = ROOT / "data/processed/multisat_2024_recent_daily_decay_kp.csv"OUT = ROOT / "results"df = pd.read_csv(DATA)df["decay_km_day"] = pd.to_numeric(    df["decay_km_day"], errors="coerce")for column in ["storm_day", "usable_decay"]:    df[column] = (        df[column].astype(str).str.lower() == "true"    )df = df[np.isfinite(df["decay_km_day"])].copy()# Positive decay = altitude decreasing.# Negative decay = altitude increasing.methods = {    "No magnitude filter":        np.ones(len(df), dtype=bool),    "Original filter":        df["usable_decay"].to_numpy(),    "Absolute change <= 0.5 km/day":        (df["decay_km_day"].abs() <= 0.5).to_numpy(),    "Absolute change <= 1.0 km/day":        (df["decay_km_day"].abs() <= 1.0).to_numpy(),    "Absolute change <= 2.0 km/day":        (df["decay_km_day"].abs() <= 2.0).to_numpy(),    "Exclude raising > 0.2 km/day":        (df["decay_km_day"] >= -0.2).to_numpy(),}MIN_STORM = 3MIN_NONSTORM = 3rows = []for method, mask in methods.items():    selected = df.loc[mask].copy()    for norad_id, g in selected.groupby("norad_id"):        storm = g.loc[g["storm_day"], "decay_km_day"]        nonstorm = g.loc[~g["storm_day"], "decay_km_day"]        if len(storm) < MIN_STORM:            continue        if len(nonstorm) < MIN_NONSTORM:            continue        rows.append({            "method": method,            "norad_id": norad_id,            "altitude_band": g["altitude_band"].iloc[0],            "n_storm": len(storm),            "n_nonstorm": len(nonstorm),            "storm_difference_km_day":                storm.mean() - nonstorm.mean()        })results = pd.DataFrame(rows)if results.empty:    raise RuntimeError("No satellites passed the requirements.")results.to_csv(    OUT / "decay_sensitivity_satellites.csv",    index=False)# Compare each method against raw data on precisely# the same satellite IDsraw = results[    results["method"] == "No magnitude filter"][["norad_id", "storm_difference_km_day"]].rename(    columns={        "storm_difference_km_day": "raw_difference"    })paired = results.merge(    raw, on="norad_id", how="inner",    validate="many_to_one")summary = (    paired.groupby(["method", "altitude_band"])    .agg(        satellites=("norad_id", "nunique"),        raw_same_satellites=("raw_difference", "median"),        screened_same_satellites=(            "storm_difference_km_day", "median"        )    )    .reset_index())summary["median_shift_km_day"] = (    summary["screened_same_satellites"]    - summary["raw_same_satellites"])summary.to_csv(    OUT / "decay_sensitivity_summary.csv",    index=False)pd.set_option("display.max_rows", 100)pd.set_option("display.width", 180)print("\nFILTER SENSITIVITY (SAME SATELLITES):")print(summary.to_string(index=False))print("\nSaved:")print("results/decay_sensitivity_satellites.csv")print("results/decay_sensitivity_summary.csv")